python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['robot0_eye_in_hand'],include_depth=True,video='none');cam=o.meta['cameras']['robot0_eye_in_hand'];T=np.array(cam['cam2world_gl']);K=np.array(cam['intrinsic_cv']);d=o.depth['robot0_eye_in_hand'][0];p=o.meta['proprio']['now'];print('q',p[26:29],'camtrans',T[:3,3]);
for y in [140,150,160,170,180]:
 row=[]
 for x in [120,130,140,150,160,170,180,190]:
  dep=float(d[y,x]);v=np.array([(x-160)*dep/K[0,0],-(y-120)*dep/K[1,1],-dep,1]);w=T@v;row.append(f'{dep:.2f}[{w[0]:.2f},{w[1]:.2f},{w[2]:.2f}]')
 print(y,' | '.join(row))
PY

